def ext_gcd(a, b):
    if b == 0: return (a, 1, 0)
    g, x1, y1 = ext_gcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)

def mod_inverse(a, m):
    g, x, _ = ext_gcd(a, m)
    return (x % m + m) % m

def chinese_remainder_theorem(num: list[int], rem: list[int]) -> int:
    prod = 1
    for n in num:
        prod *= n
    result = 0
    for i in range(len(num)):
        pp = prod // num[i]
        result += rem[i] * mod_inverse(pp, num[i]) * pp
    return result % prod

